CREATE TABLE `backup_deletion_log` (
    `deletion_id` bigint NOT NULL AUTO_INCREMENT,
    `table_name` varchar(64) NOT NULL,
    `record_key` json NOT NULL,
    `deleted_at` timestamp(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
    PRIMARY KEY (`deletion_id`),
    KEY `idx_backup_deletion_window` (`table_name`, `deleted_at`, `deletion_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

ALTER TABLE `player` ADD COLUMN `created_at` timestamp(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6), ADD COLUMN `updated_at` timestamp(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6), ADD KEY `idx_player_backup_updated` (`updated_at`);
