CREATE TRIGGER `backup_delete_player` AFTER DELETE ON `player` FOR EACH ROW INSERT INTO `backup_deletion_log` (`table_name`,`record_key`) VALUES ('player', JSON_OBJECT('player_id', OLD.`player_id`));
